1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"strconv"
8		"strings"
9		"time"
10	)
11	
12	// 升级阶段标识。
13	const (
14		StageDownload = "download"
15		StageInstall  = "install"
16		StageRollback = "rollback"
17	)
18	
19	// 活动与设备在活动中的状态。
20	const (
21		CampaignRunning   = "running"
22		CampaignSucceeded = "succeeded"
23		CampaignFailed    = "failed"
24	
25		DevicePending     = "pending"     // 尚未领取下载
26		DeviceDownloading = "downloading" // 已领取下载，未完成
27		DeviceReady       = "ready"       // 下载成功，安装尚未领取
28		DeviceInstalling  = "installing"  // 已领取安装，未完成
29		DeviceSucceeded   = "succeeded"
30		DeviceFailed      = "failed"
31		DeviceTimeout     = "timeout"
32		DeviceSkipped     = "skipped" // 前序批次失败后，后续批次记为未执行
33	
34		// 回滚相关状态，仅出现在开启回滚的活动中。
35		DeviceAwaitingRollback  = "awaiting_rollback" // 安装失败已接受，等待领取回滚
36		DeviceRollingBack       = "rolling_back"      // 已领取回滚，未完成
37		DeviceRollbackSucceeded = "rollback_succeeded"
38		DeviceRollbackFailed    = "rollback_failed"
39		DeviceRollbackTimeout   = "rollback_timeout" // 到达截止时间时回滚仍未完成
40	)
41	
42	// VersionSpec 是一个已登记的升级目标版本及其允许的当前版本。
43	type VersionSpec struct {
44		// Target 是目标版本，与设备当前版本按字符串精确匹配。
45		Target string
46		// AllowedFrom 是允许升级到目标版本的当前版本列表。
47		AllowedFrom []string
48	}
49	
50	// versionState 是升级版本登记的内部状态。
51	type versionState struct {
52		Target      string
53		AllowedFrom []string
54	}
55	
56	// CampaignSpec 描述创建分批升级活动所需的全部信息。
57	type CampaignSpec struct {
58		// ID 是活动唯一标识，不能为空。
59		ID string
60		// Operator 是创建活动的操作者，不能为空。
61		Operator string
62		// CreatedAt 是活动创建时间。
63		CreatedAt time.Time
64		// TargetVersion 是已登记的目标版本。
65		TargetVersion string
66		// Devices 是按提交次序排列的有序设备列表，不能为空、不能重复。
67		Devices []string
68		// BatchSize 是批大小，必须是正整数。
69		BatchSize int
70		// WindowStart/WindowEnd 是维护窗口，开始时刻须早于结束时刻；
71		// 窗口包含开始时刻、不包含结束时刻。
72		WindowStart time.Time
73		WindowEnd   time.Time
74		// Deadline 是截止时间，必须晚于创建时间。
75		Deadline time.Time
76		// RollbackOnFailure 开启安装失败后的自动回滚，默认关闭。
77		// 关闭时安装失败即设备失败；开启后安装失败会先等待设备回滚到
78		// 首次领取下载时锁定的当前版本，活动最终仍为失败。
79		RollbackOnFailure bool
80	}
81	
82	// Operation 是派发给设备的一个升级操作。
83	type Operation struct {
84		// ID 是操作的稳定标识，重复查询未完成操作时保持不变，重开存储后仍有效。
85		ID         string
86		CampaignID string
87		DeviceID   string
88		// Kind 是 StageDownload、StageInstall 或 StageRollback。
89		Kind string
90		// TargetVersion 仅在回滚操作上有值，指明必须恢复到的锁定版本，
91		// 让设备明确知道要恢复哪个版本；下载与安装操作为空。
92		TargetVersion string
93	}
94	
95	// OperationResult 是设备提交的一次操作结果。
96	// 每次结果必须带活动、设备、操作标识及发生时间。
97	// 安装成功（Success 且操作是 install）时还须附带符合上报规则的设备上报：
98	// 正整数 Seq、等于目标版本的 Version 和完整 JSON 对象 Config。
99	// 回滚成功（Success 且操作是 rollback）时同样须附带上报，
100	// 但 Version 必须等于领取下载时锁定的回滚目标版本。
101	type OperationResult struct {
102		CampaignID  string
103		DeviceID    string
104		OperationID string
105		At          time.Time
106		Success     bool
107		// Reason 在失败时必填。
108		Reason string
109		// 安装成功时附带的设备上报。
110		Seq     uint64
111		Version string
112		Config  json.RawMessage
113	}
114	
115	// ResultRecord 是结果历史中的一条记录，按接受顺序保存。
116	type ResultRecord struct {
117		DeviceID    string
118		OperationID string
119		Stage       string
120		Success     bool
121		Reason      string
122		// Version 为安装或回滚成功时上报的版本，其余为空。
123		Version string
124		At      time.Time
125	}
126	
127	// opState 是单个设备单个阶段的操作与结果状态。
128	type opState struct {
129		ID string
130		// Claimed 表示操作是否已被领取；未领取的操作不能提交结果。
131		Claimed   bool
132		ClaimedAt time.Time
133		// 已接受的结果。
134		HasResult     bool
135		Success       bool
136		Reason        string
137		At            time.Time
138		ResultSeq     uint64
139		ResultVersion string
140		ResultConfig  json.RawMessage
141	}
142	
143	// campaignDevice 是单台设备在一个活动中的完整状态。
144	type campaignDevice struct {
145		DeviceID string
146		Batch    int
147		Download opState
148		Install  opState
149		// Rollback 是安装失败后的回滚操作，仅在开启回滚的活动中使用。
150		Rollback opState
151		// RollbackTarget 是首次领取下载时锁定的设备当前版本，回滚必须恢复到它。
152		// 后续普通上报不改变它，也不要求它另行登记为升级目标。
153		RollbackTarget string
154		// Status/Phase/Reason/At 描述设备当前状态；
155		// failed 必须记录阶段、原因和时间；timeout/skipped 同理。
156		Status string
157		Phase  string
158		Reason string
159		At     time.Time
160	}
161	
162	// campaignState 是一个分批升级活动的内部状态。
163	type campaignState struct {
164		ID          string
165		Operator    string
166		Target      string
167		CreatedAt   time.Time
168		BatchSize   int
169		WindowStart time.Time
170		WindowEnd   time.Time
171		Deadline    time.Time
172		// RollbackOnFailure 表示安装失败后是否进入回滚；旧存储缺省为关闭。
173		RollbackOnFailure bool
174		Devices           []*campaignDevice
175		index             map[string]int
176		Results           []ResultRecord
177		// idScheme 是操作标识方案（opIDScheme*），随活动持久化；
178		// 修复前保存的活动为 opIDSchemeLegacy，新活动为 opIDSchemeV2。
179		idScheme int
180		// LastTime 是本活动已接受的最晚时间，用于拒绝时间倒退。
181		LastTime time.Time
182		Status   string
183		Ended    bool
184		EndedAt  time.Time
185	}
186	
187	// RegisterUpgrade 登记一个升级目标版本及允许升级的当前版本列表。
188	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
189	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
190	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		if err := s.checkOpen(); err != nil {
194			return err
195		}
196		if targetVersion == "" {
197			return ErrInvalidVersion
198		}
199		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
200			return err
201		}
202		if _, ok := s.versions[targetVersion]; ok {
203			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
204		}
205		from := append([]string(nil), allowedFrom...)
206		return s.commit(func() error {
207			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
208			return nil
209		})
210	}
211	
212	func validateAllowedFrom(target string, allowedFrom []string) error {
213		if len(allowedFrom) == 0 {
214			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
215		}
216		for _, v := range allowedFrom {
217			if v == "" {
218				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
219			}
220			if v == target {
221				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
222			}
223		}
224		return nil
225	}
226	
227	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
228	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
229	func (s *Store) CreateCampaign(spec CampaignSpec) error {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		if err := s.checkOpen(); err != nil {
233			return err
234		}
235		// 先做全部校验，全部通过后才写入，保证原子创建。
236		if spec.ID == "" {
237			return ErrInvalidCampaignID
238		}
239		if spec.Operator == "" {
240			return ErrInvalidOperator
241		}
242		if spec.CreatedAt.IsZero() {
243			return fmt.Errorf("%w: created at", ErrInvalidTime)
244		}
245		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
246			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
247		}
248		if spec.Deadline.IsZero() {
249			return fmt.Errorf("%w: deadline", ErrInvalidTime)
250		}
251		if len(spec.Devices) == 0 {
252			return ErrInvalidDeviceList
253		}
254		seen := make(map[string]bool, len(spec.Devices))
255		for _, id := range spec.Devices {
256			if id == "" {
257				return ErrInvalidDeviceID
258			}
259			if seen[id] {
260				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
261			}
262			seen[id] = true
263		}
264		if spec.BatchSize <= 0 {
265			return ErrInvalidBatchSize
266		}
267		if !spec.WindowStart.Before(spec.WindowEnd) {
268			return ErrInvalidWindow
269		}
270		if !spec.Deadline.After(spec.CreatedAt) {
271			return ErrInvalidDeadline
272		}
273		if spec.TargetVersion == "" {
274			return ErrInvalidVersion
275		}
276		if _, ok := s.versions[spec.TargetVersion]; !ok {
277			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
278		}
279		if _, ok := s.campaigns[spec.ID]; ok {
280			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
281		}
282		ver := s.versions[spec.TargetVersion]
283		// 新标识不能与存储内其他操作的标识相同，同一设备不同阶段也不共用：
284		// v2 编码本身按（活动, 设备, 阶段）区分，nonce 再避开与旧方案标识的偶然相同。
285		taken := s.takenOperationIDs()
286		newOpID := func(deviceID, stage string) string {
287			for nonce := 0; ; nonce++ {
288				id := encodeOperationIDV2(nonce, spec.ID, deviceID, stage)
289				if !taken[id] {
290					taken[id] = true
291					return id
292				}
293			}
294		}
295		devs := make([]*campaignDevice, 0, len(spec.Devices))
296		for i, id := range spec.Devices {
297			d, ok := s.devices[id]
298			if !ok {
299				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
300			}
301			if !containsString(ver.AllowedFrom, d.Version) {
302				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
303			}
304			if s.deviceBusy(id, spec.ID) {
305				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
306			}
307			devs = append(devs, &campaignDevice{
308				DeviceID: id,
309				Batch:    i / spec.BatchSize,
310				Status:   DevicePending,
311				Phase:    StageDownload,
312				Download: opState{ID: newOpID(id, StageDownload)},
313				Install:  opState{ID: newOpID(id, StageInstall)},
314				Rollback: opState{ID: newOpID(id, StageRollback)},
315			})
316		}
317		campaign := &campaignState{
318			ID:                spec.ID,
319			Operator:          spec.Operator,
320			Target:            spec.TargetVersion,
321			CreatedAt:         spec.CreatedAt,
322			BatchSize:         spec.BatchSize,
323			WindowStart:       spec.WindowStart,
324			WindowEnd:         spec.WindowEnd,
325			Deadline:          spec.Deadline,
326			RollbackOnFailure: spec.RollbackOnFailure,
327			Devices:           devs,
328			index:             make(map[string]int, len(devs)),
329			idScheme:          opIDSchemeV2,
330			LastTime:          spec.CreatedAt,
331			Status:            CampaignRunning,
332		}
333		for i, cd := range devs {
334			campaign.index[cd.DeviceID] = i
335		}
336		return s.commit(func() error {
337			s.campaigns[spec.ID] = campaign
338			return nil
339		})
340	}
341	
342	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
343	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
344		for id, c := range s.campaigns {
345			if id == excludeCampaign || c.Ended {
346				continue
347			}
348			if _, ok := c.index[deviceID]; ok {
349				return true
350			}
351		}
352		return false
353	}
354	
355	// operationID 是修复前的旧标识方案：冒号拼接。活动或设备标识含冒号时，
356	// 不同（活动, 设备）组合会拼出相同标识，仅用于兼容校验修复前保存的活动；
357	// 新活动一律使用 encodeOperationIDV2。
358	func operationID(campaignID, deviceID, stage string) string {
359		return campaignID + ":" + deviceID + ":" + stage
360	}
361	
362	// 操作标识方案编号，随活动一起持久化；缺省（旧存储）为旧方案。
363	const (
364		opIDSchemeLegacy = 0
365		opIDSchemeV2     = 1
366	)
367	
368	const opIDV2Prefix = "v2:"
369	
370	// encodeOperationIDV2 生成无歧义的操作标识：活动与设备标识用长度前缀编码，
371	// 任何非空标识（含冒号、中文等）都按原字符串精确保留，（活动, 设备, 阶段）
372	// 三元组与标识一一对应。nonce 用于避开与存储内已有标识（如旧方案标识）
373	// 偶然相同的情形。
374	func encodeOperationIDV2(nonce int, campaignID, deviceID, stage string) string {
375		return fmt.Sprintf("v2:%d:%d:%s%d:%s%s",
376			nonce, len(campaignID), campaignID, len(deviceID), deviceID, stage)
377	}
378	
379	// parseOperationIDV2 解析 v2 操作标识，还原活动、设备与阶段。
380	// 只接受规范编码（解析后原样重编码必须等于入参）。
381	func parseOperationIDV2(id string) (campaignID, deviceID, stage string, ok bool) {
382		rest, found := strings.CutPrefix(id, opIDV2Prefix)
383		if !found {
384			return "", "", "", false
385		}
386		readInt := func() (int, bool) {
387			i := strings.IndexByte(rest, ':')
388			if i <= 0 {
389				return 0, false
390			}
391			n, err := strconv.Atoi(rest[:i])
392			if err != nil || n < 0 {
393				return 0, false
394			}
395			rest = rest[i+1:]
396			return n, true
397		}
398		readStr := func(n int) (string, bool) {
399			if n <= 0 || len(rest) < n {
400				return "", false
401			}
402			s := rest[:n]
403			rest = rest[n:]
404			return s, true
405		}
406		nonce, ok1 := readInt()
407		lenC, ok2 := readInt()
408		if !ok1 || !ok2 {
409			return "", "", "", false
410		}
411		campaignID, ok1 = readStr(lenC)
412		lenD, ok2 := readInt()
413		if !ok1 || !ok2 {
414			return "", "", "", false
415		}
416		deviceID, ok1 = readStr(lenD)
417		if !ok1 {
418			return "", "", "", false
419		}
420		stage = rest
421		if !validStage(stage) || encodeOperationIDV2(nonce, campaignID, deviceID, stage) != id {
422			return "", "", "", false
423		}
424		return campaignID, deviceID, stage, true
425	}
426	
427	func validStage(stage string) bool {
428		return stage == StageDownload || stage == StageInstall || stage == StageRollback
429	}
430	
431	// validV2OpID 校验标识是否是指定（活动, 设备, 阶段）的规范 v2 操作标识。
432	func validV2OpID(opID, campaignID, deviceID, stage string) bool {
433		cid, did, st, ok := parseOperationIDV2(opID)
434		return ok && cid == campaignID && did == deviceID && st == stage
435	}
436	
437	// takenOperationIDs 收集存储内全部活动（含已结束）正在使用或结果历史中
438	// 出现过的操作标识，供新活动生成标识时避开相同值。
439	func (s *Store) takenOperationIDs() map[string]bool {
440		taken := map[string]bool{}
441		for _, c := range s.campaigns {
442			for _, cd := range c.Devices {
443				taken[cd.Download.ID] = true
444				taken[cd.Install.ID] = true
445				if cd.Rollback.ID != "" {
446					taken[cd.Rollback.ID] = true
447				}
448			}
449			for _, r := range c.Results {
450				taken[r.OperationID] = true
451			}
452		}
453		return taken
454	}
455	
456	func containsString(list []string, v string) bool {
457		for _, x := range list {
458			if x == v {
459				return true
460			}
461		}
462		return false
463	}
464	
465	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
466	//
467	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
468	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
469	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
470	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
471	// 后续普通上报不改变它。
472	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
473	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
474	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
475	// 且可在窗口外、截止前提交结果。
476	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
477	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
478	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
479	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
480		s.mu.Lock()
481		defer s.mu.Unlock()
482		if err := s.checkOpen(); err != nil {
483			return nil, err
484		}
485		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
486		if err != nil {
487			return nil, err
488		}
489		if at.IsZero() {
490			return nil, ErrInvalidTime
491		}
492		if at.Before(c.LastTime) {
493			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
494		}
495		var op *Operation
496		var reject error
497		err = s.commit(func() error {
498			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
499			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
500			if !at.Before(c.Deadline) {
501				c.LastTime = at
502				s.applyTimeout(c, at)
503				reject = ErrCampaignEnded
504				return nil
505			}
506			if c.Ended {
507				// 纯拒绝路径：不推进时间基线，不改状态。
508				reject = ErrCampaignEnded
509				return nil
510			}
511			if isTerminal(cd.Status) {
512				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
513				return nil
514			}
515			c.LastTime = at
516			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
517			if out := outstandingOp(c, cd); out != nil {
518				op = out
519				return nil
520			}
521			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
522			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
523			if cd.Status == DeviceAwaitingRollback {
524				if !s.devices[deviceID].Online {
525					return nil
526				}
527				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
528					return nil
529				}
530				cd.Rollback.Claimed = true
531				cd.Rollback.ClaimedAt = at
532				cd.Status = DeviceRollingBack
533				cd.Phase = StageRollback
534				cd.At = at
535				op = &Operation{
536					ID:            cd.Rollback.ID,
537					CampaignID:    c.ID,
538					DeviceID:      deviceID,
539					Kind:          StageRollback,
540					TargetVersion: cd.RollbackTarget,
541				}
542				return nil
543			}
544			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
545			if !s.batchOpen(c, cd) {
546				return nil
547			}
548			if !s.devices[deviceID].Online {
549				return nil // 离线保留待办，上线后继续
550			}
551			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
552				return nil // 窗口外不派发新操作；窗口为 [start, end)
553			}
554			if !cd.Download.Claimed {
555				// 首次领取下载前再次检查当前版本。
556				current := s.devices[deviceID].Version
557				if !containsString(s.versions[c.Target].AllowedFrom, current) {
558					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
559					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
560					cd.Download.Claimed = true
561					cd.Download.ClaimedAt = at
562					cd.Download.HasResult = true
563					cd.Download.Success = false
564					cd.Download.Reason = reason
565					cd.Download.At = at
566					s.failDevice(c, cd, StageDownload, reason, at)
567					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
568					return nil
569				}
570				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
571				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
572				if c.RollbackOnFailure && cd.RollbackTarget == "" {
573					cd.RollbackTarget = current
574				}
575				cd.Download.Claimed = true
576				cd.Download.ClaimedAt = at
577				cd.Status = DeviceDownloading
578				cd.At = at
579				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
580				return nil
581			}
582			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
583			cd.Install.Claimed = true
584			cd.Install.ClaimedAt = at
585			cd.Status = DeviceInstalling
586			cd.At = at
587			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
588			return nil
589		})
590		if err != nil {
591			return nil, err
592		}
593		if reject != nil {
594			return nil, reject
595		}
596		return op, nil
597	}
598	
599	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
600	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
601		switch {
602		case cd.Download.Claimed && !cd.Download.HasResult:
603			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
604		case cd.Install.Claimed && !cd.Install.HasResult:
605			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
606		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
607			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
608			return &Operation{
609				ID:            cd.Rollback.ID,
610				CampaignID:    c.ID,
611				DeviceID:      cd.DeviceID,
612				Kind:          StageRollback,
613				TargetVersion: cd.RollbackTarget,
614			}
615		default:
616			return nil
617		}
618	}
619	
620	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
621	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
622		for _, other := range c.Devices {
623			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
624				return false
625			}
626		}
627		return true
628	}
629	
630	// SubmitResult 接收设备提交的操作结果。
631	//
632	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
633	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
634	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
635	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
636	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
637	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
638	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
639	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
640	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到：
641	// 不校验附带上报与失败原因、不接收为操作结果，直接按截止处理——未结束设备
642	// 全部超时（等待或正在回滚的记回滚超时），活动以失败结束，返回 ErrCampaignEnded。
643	// 普通设备上报不经过本方法，也不会推进活动。
644	func (s *Store) SubmitResult(res OperationResult) error {
645		s.mu.Lock()
646		defer s.mu.Unlock()
647		if err := s.checkOpen(); err != nil {
648			return err
649		}
650		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
651		if err != nil {
652			return err
653		}
654		if res.At.IsZero() {
655			return ErrInvalidTime
656		}
657		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
658		var stage string
659		var op *opState
660		switch res.OperationID {
661		case cd.Download.ID:
662			stage, op = StageDownload, &cd.Download
663		case cd.Install.ID:
664			stage, op = StageInstall, &cd.Install
665		case cd.Rollback.ID:
666			stage, op = StageRollback, &cd.Rollback
667		default:
668			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
669		}
670		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
671		// 不推进时间基线；不同结果冲突。均不改变状态。
672		if op.HasResult {
673			if resultMatches(op, res) {
674				return nil
675			}
676			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
677		}
678		if res.At.Before(c.LastTime) {
679			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
680		}
681		if !op.Claimed {
682			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
683			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
684		}
685		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
686		// 不再接收为操作结果，也不校验附带上报或失败原因——直接按截止处理：
687		// 未结束设备全部超时（等待/正在回滚的记回滚超时），活动以失败结束，
688		// 状态时间与活动结束时间采用本次提交时间，返回 ErrCampaignEnded。
689		// 活动可能已被显式推进到截止而结束：applyTimeout 对已结束活动是空操作，
690		// 结果仍按截止拒绝，不能因附带配置非法或缺少原因改成相应的校验错误。
691		if !res.At.Before(c.Deadline) {
692			if err := s.commit(func() error {
693				c.LastTime = res.At
694				s.applyTimeout(c, res.At)
695				return nil
696			}); err != nil {
697				return err
698			}
699			return ErrCampaignEnded
700		}
701		if !res.Success && res.Reason == "" {
702			return ErrInvalidReason
703		}
704		// 安装/回滚成功附带的设备上报与普通 Report 共用 checkReport 的同一套
705		// 规则（必填字段、版本约束、序号过旧/重复/冲突）；这里先校验并记下判定，
706		// 实际写入在下面的同一次 commit 内与活动、历史一起完成。附带上报任何
707		// 不合规都映射为 ErrInvalidReport，不改成普通上报的错误类别。
708		var repIn reportInput
709		var repCfg json.RawMessage
710		var repVerdict reportVerdict
711		if res.Success && (stage == StageInstall || stage == StageRollback) {
712			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
713			wantVersion := c.Target
714			if stage == StageRollback {
715				wantVersion = cd.RollbackTarget
716			}
717			repIn = reportInput{
718				DeviceID: res.DeviceID,
719				Seq:      res.Seq,
720				At:       res.At,
721				Version:  res.Version,
722				Config:   res.Config,
723			}
724			var checkErr error
725			repCfg, repVerdict, checkErr = checkReport(s.devices[res.DeviceID], repIn, wantVersion)
726			if checkErr != nil {
727				return reportAttachedError(checkErr.(errBadReport))
728			}
729		}
730		var reject error
731		err = s.commit(func() error {
732			// 活动已结束且提交时间越过截止时间：只推进时间基线并拒绝
733			// （未结束活动的截止处理已在提交前完成，不会到达这里）。
734			if !res.At.Before(c.Deadline) {
735				c.LastTime = res.At
736				s.applyTimeout(c, res.At)
737				reject = ErrCampaignEnded
738				return nil
739			}
740			if c.Ended {
741				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
742				reject = ErrCampaignEnded
743				return nil
744			}
745			if isTerminal(cd.Status) {
746				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
747				return nil
748			}
749			c.LastTime = res.At
750			op.HasResult = true
751			op.Success = res.Success
752			op.Reason = res.Reason
753			op.At = res.At
754			if !res.Success {
755				switch {
756				case stage == StageInstall && c.RollbackOnFailure:
757					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
758					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
759					s.enterRollback(c, cd, res.Reason, res.At)
760				case stage == StageRollback:
761					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
762					s.finishRollbackFailure(c, cd, res.Reason, res.At)
763				default:
764					s.failDevice(c, cd, stage, res.Reason, res.At)
765				}
766				return nil
767			}
768			switch stage {
769			case StageDownload:
770				cd.Status = DeviceReady
771				cd.Phase = StageInstall
772				cd.Reason = ""
773				cd.At = res.At
774			case StageInstall:
775				// 安装成功：附带上报与活动同时更新、一起持久化。
776				// 同序号的完全重复上报不重新写入影子（不刷新在线状态与差异时间）。
777				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
778				op.ResultSeq = res.Seq
779				op.ResultVersion = res.Version
780				op.ResultConfig = cloneRaw(res.Config)
781				cd.Status = DeviceSucceeded
782				cd.Phase = StageInstall
783				cd.Reason = ""
784				cd.At = res.At
785			case StageRollback:
786				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
787				// 期望配置、修订号与审计保持不变；重复上报不重新写入影子。
788				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
789				op.ResultSeq = res.Seq
790				op.ResultVersion = res.Version
791				op.ResultConfig = cloneRaw(res.Config)
792				cd.Status = DeviceRollbackSucceeded
793				cd.Phase = StageRollback
794				cd.Reason = ""
795				cd.At = res.At
796			}
797			c.Results = append(c.Results, ResultRecord{
798				DeviceID:    cd.DeviceID,
799				OperationID: op.ID,
800				Stage:       stage,
801				Success:     true,
802				Version:     op.ResultVersion,
803				At:          res.At,
804			})
805			s.settle(c, res.At)
806			return nil
807		})
808		if err != nil {
809			return err
810		}
811		return reject
812	}
813	
814	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
815	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
816	// 使活动结束后的重复提交仍然有效。
817	func resultMatches(op *opState, res OperationResult) bool {
818		if op.Success != res.Success || op.Reason != res.Reason {
819			return false
820		}
821		if op.Success && op.ResultSeq != 0 {
822			return op.ResultSeq == res.Seq &&
823				op.ResultVersion == res.Version &&
824				rawEqual(op.ResultConfig, res.Config)
825		}
826		return true
827	}
828	
829	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
830	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
831	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
832	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
833		cd.Status = DeviceAwaitingRollback
834		cd.Phase = StageRollback
835		cd.Reason = reason
836		cd.At = at
837		c.Results = append(c.Results, ResultRecord{
838			DeviceID:    cd.DeviceID,
839			OperationID: cd.Install.ID,
840			Stage:       StageInstall,
841			Success:     false,
842			Reason:      reason,
843			At:          at,
844		})
845		skipLaterBatches(c, cd, at)
846		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
847	}
848	
849	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
850	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
851	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
852		cd.Status = DeviceRollbackFailed
853		cd.Phase = StageRollback
854		cd.Reason = reason
855		cd.At = at
856		c.Results = append(c.Results, ResultRecord{
857			DeviceID:    cd.DeviceID,
858			OperationID: cd.Rollback.ID,
859			Stage:       StageRollback,
860			Success:     false,
861			Reason:      reason,
862			At:          at,
863		})
864		s.settle(c, at)
865	}
866	
867	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
868	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
869		for _, other := range c.Devices {
870			if other.Batch > cd.Batch && !isTerminal(other.Status) {
871				other.Status = DeviceSkipped
872				other.Phase = pendingPhase(other)
873				other.Reason = "not executed: previous batch failed"
874				other.At = at
875			}
876		}
877	}
878	
879	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
880	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
881	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
882		cd.Status = DeviceFailed
883		cd.Phase = phase
884		cd.Reason = reason
885		cd.At = at
886		c.Results = append(c.Results, ResultRecord{
887			DeviceID:    cd.DeviceID,
888			OperationID: opIDFor(cd, phase),
889			Stage:       phase,
890			Success:     false,
891			Reason:      reason,
892			At:          at,
893		})
894		skipLaterBatches(c, cd, at)
895		s.settle(c, at)
896	}
897	
898	func opIDFor(cd *campaignDevice, phase string) string {
899		switch phase {
900		case StageInstall:
901			return cd.Install.ID
902		case StageRollback:
903			return cd.Rollback.ID
904		default:
905			return cd.Download.ID
906		}
907	}
908	
909	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
910	func pendingPhase(cd *campaignDevice) string {
911		if cd.Download.HasResult && cd.Download.Success {
912			return StageInstall
913		}
914		return StageDownload
915	}
916	
917	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
918	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
919	// 以回滚阶段超时结束；不改写或清空影子。
920	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
921		if c.Ended {
922			return
923		}
924		for _, cd := range c.Devices {
925			if isTerminal(cd.Status) {
926				continue
927			}
928			switch cd.Status {
929			case DeviceAwaitingRollback, DeviceRollingBack:
930				cd.Status = DeviceRollbackTimeout
931				cd.Phase = StageRollback
932			default:
933				cd.Status = DeviceTimeout
934				cd.Phase = pendingPhase(cd)
935			}
936			cd.Reason = "deadline exceeded"
937			cd.At = at
938		}
939		c.Status = CampaignFailed
940		c.Ended = true
941		c.EndedAt = at
942	}
943	
944	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
945	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
946	func (s *Store) settle(c *campaignState, at time.Time) {
947		allSucceeded := true
948		for _, cd := range c.Devices {
949			if !isTerminal(cd.Status) {
950				return
951			}
952			if cd.Status != DeviceSucceeded {
953				allSucceeded = false
954			}
955		}
956		c.Ended = true
957		c.EndedAt = at
958		if allSucceeded {
959			c.Status = CampaignSucceeded
960		} else {
961			c.Status = CampaignFailed
962		}
963	}
964	
965	func isTerminal(status string) bool {
966		switch status {
967		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
968			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
969			return true
970		default:
971			return false
972		}
973	}
974	
975	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
976	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
977	// 未到截止时间或活动已结束时为空操作。
978	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
979		s.mu.Lock()
980		defer s.mu.Unlock()
981		if err := s.checkOpen(); err != nil {
982			return err
983		}
984		c, err := s.lookupCampaign(campaignID)
985		if err != nil {
986			return err
987		}
988		if at.IsZero() {
989			return ErrInvalidTime
990		}
991		if at.Before(c.LastTime) {
992			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
993		}
994		if c.Ended {
995			return nil
996		}
997		if at.Before(c.Deadline) {
998			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
999			return s.commit(func() error { c.LastTime = at; return nil })
1000		}
1001		return s.commit(func() error {
1002			c.LastTime = at
1003			s.applyTimeout(c, at)
1004			return nil
1005		})
1006	}
1007	
1008	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
1009		if campaignID == "" {
1010			return nil, ErrInvalidCampaignID
1011		}
1012		c, ok := s.campaigns[campaignID]
1013		if !ok {
1014			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
1015		}
1016		return c, nil
1017	}
1018	
1019	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
1020		c, err := s.lookupCampaign(campaignID)
1021		if err != nil {
1022			return nil, nil, err
1023		}
1024		if deviceID == "" {
1025			return nil, nil, ErrInvalidDeviceID
1026		}
1027		i, ok := c.index[deviceID]
1028		if !ok {
1029			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
1030		}
1031		return c, c.Devices[i], nil
1032	}
1033	
1034	// DeviceStatusView 是一台设备在活动中的状态快照。
1035	type DeviceStatusView struct {
1036		DeviceID string
1037		Batch    int
1038		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
1039		// 回滚失败与回滚阶段超时。
1040		Status string
1041		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
1042		Phase string
1043		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
1044		Reason string
1045		// At 是进入当前状态的时间。
1046		At time.Time
1047		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
1048		DownloadID string
1049		InstallID  string
1050		RollbackID string
1051		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
1052		RollbackTarget string
1053		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
1054		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
1055		InstallFailReason string
1056		InstallFailAt     time.Time
1057		// RollbackResult 表示是否已接受回滚结果。
1058		RollbackResult bool
1059		// RollbackSuccess 表示已接受的回滚结果是否成功。
1060		RollbackSuccess bool
1061		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
1062		RollbackReason string
1063		RollbackAt     time.Time
1064	}
1065	
1066	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
1067	type BatchView struct {
1068		Index   int
1069		Devices []DeviceStatusView
1070	}
1071	
1072	// CampaignView 是分批升级活动的只读快照。
1073	type CampaignView struct {
1074		ID            string
1075		Operator      string
1076		TargetVersion string
1077		CreatedAt     time.Time
1078		BatchSize     int
1079		WindowStart   time.Time
1080		WindowEnd     time.Time
1081		Deadline      time.Time
1082		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
1083		RollbackOnFailure bool
1084		// Status 取 Campaign* 状态常量。
1085		Status  string
1086		Ended   bool
1087		EndedAt time.Time
1088		// Devices 按提交次序给出每台设备的状态。
1089		Devices []DeviceStatusView
1090		// Batches 按批次号分组，保留设备提交次序。
1091		Batches []BatchView
1092		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
1093		Results []ResultRecord
1094	}
1095	
1096	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1097	// 失败或超时原因及结果历史。返回数据为独立副本。
1098	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1099		s.mu.Lock()
1100		defer s.mu.Unlock()
1101		if err := s.checkOpen(); err != nil {
1102			return CampaignView{}, err
1103		}
1104		c, err := s.lookupCampaign(campaignID)
1105		if err != nil {
1106			return CampaignView{}, err
1107		}
1108		v := CampaignView{
1109			ID:                c.ID,
1110			Operator:          c.Operator,
1111			TargetVersion:     c.Target,
1112			CreatedAt:         c.CreatedAt,
1113			BatchSize:         c.BatchSize,
1114			WindowStart:       c.WindowStart,
1115			WindowEnd:         c.WindowEnd,
1116			Deadline:          c.Deadline,
1117			RollbackOnFailure: c.RollbackOnFailure,
1118			Status:            c.Status,
1119			Ended:             c.Ended,
1120			EndedAt:           c.EndedAt,
1121			Results:           make([]ResultRecord, len(c.Results)),
1122		}
1123		copy(v.Results, c.Results)
1124		for _, cd := range c.Devices {
1125			dv := DeviceStatusView{
1126				DeviceID:       cd.DeviceID,
1127				Batch:          cd.Batch,
1128				Status:         cd.Status,
1129				Phase:          cd.Phase,
1130				Reason:         cd.Reason,
1131				At:             cd.At,
1132				DownloadID:     cd.Download.ID,
1133				InstallID:      cd.Install.ID,
1134				RollbackID:     cd.Rollback.ID,
1135				RollbackTarget: cd.RollbackTarget,
1136			}
1137			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1138			if cd.Install.HasResult && !cd.Install.Success {
1139				dv.InstallFailReason = cd.Install.Reason
1140				dv.InstallFailAt = cd.Install.At
1141			}
1142			// 回滚结果的原因与时间单独呈现。
1143			if cd.Rollback.HasResult {
1144				dv.RollbackResult = true
1145				dv.RollbackSuccess = cd.Rollback.Success
1146				dv.RollbackReason = cd.Rollback.Reason
1147				dv.RollbackAt = cd.Rollback.At
1148			}
1149			v.Devices = append(v.Devices, dv)
1150			for len(v.Batches) <= cd.Batch {
1151				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1152			}
1153			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1154		}
1155		return v, nil
1156	}
1157	
1158	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1159	type DeviceWork struct {
1160		DeviceID string
1161		Version  string
1162		Online   bool
1163		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1164		CampaignID string
1165		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1166		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1167		Pending *Operation
1168		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1169		PendingClaimed bool
1170	}
1171	
1172	// GetDeviceWork 查询设备当前版本及其待执行操作。
1173	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1174		s.mu.Lock()
1175		defer s.mu.Unlock()
1176		if err := s.checkOpen(); err != nil {
1177			return DeviceWork{}, err
1178		}
1179		d, err := s.lookup(deviceID)
1180		if err != nil {
1181			return DeviceWork{}, err
1182		}
1183		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1184		for id, c := range s.campaigns {
1185			if c.Ended {
1186				continue
1187			}
1188			i, ok := c.index[deviceID]
1189			if !ok {
1190				continue
1191			}
1192			cd := c.Devices[i]
1193			w.CampaignID = id
1194			if out := outstandingOp(c, cd); out != nil {
1195				w.Pending = out
1196				w.PendingClaimed = true
1197			} else if cd.Status == DeviceAwaitingRollback {
1198				// 回滚待领取：显示回滚目标，标记为尚未领取。
1199				w.Pending = &Operation{
1200					ID:            cd.Rollback.ID,
1201					CampaignID:    c.ID,
1202					DeviceID:      deviceID,
1203					Kind:          StageRollback,
1204					TargetVersion: cd.RollbackTarget,
1205				}
1206				w.PendingClaimed = false
1207			} else if !isTerminal(cd.Status) {
1208				kind := StageDownload
1209				id := cd.Download.ID
1210				if cd.Download.HasResult {
1211					kind, id = StageInstall, cd.Install.ID
1212				}
1213				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1214				w.PendingClaimed = false
1215			}
1216			break
1217		}
1218		return w, nil
1219	}
1220	
1221	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1222	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1223		s.mu.Lock()
1224		defer s.mu.Unlock()
1225		if err := s.checkOpen(); err != nil {
1226			return nil, err
1227		}
1228		out := make([]VersionSpec, 0, len(s.versions))
1229		for _, v := range s.versions {
1230			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1231		}
1232		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1233		return out, nil
1234	}
